rules.remediationScript:
Import-Module Microsoft.Graph.DeviceManagement

# Vervang door de policy-id (uit de finding/observedValue) en de doelgroep.
$compliancePolicyId = '<device-compliance-policy-id>'
$targetGroupId = '<object-id-van-doelgroep>'

$params = @{
    Assignments = @(
        @{
            Target = @{
                '@odata.type' = '#microsoft.graph.groupAssignmentTarget'
                GroupId = $targetGroupId
            }
        }
    )
}
New-MgDeviceManagementDeviceCompliancePolicyAssignment -DeviceCompliancePolicyId $compliancePolicyId -BodyParameter $params
